  !<     rocsparse_coosort_buffer_size(handle,
  !<                                   m,
  !<                                   n,
  !<                                   nnz,
  !<                                   coo_row_ind,
  !<                                   coo_col_ind,
  !<                                   &buffer_size);
  !<     hipMalloc(&temp_buffer, buffer_size);
  !< 
  !<     // Sort the COO matrix
  !<     rocsparse_coosort_by_column(handle,
  !<                                 m,
  !<                                 n,
  !<                                 nnz,
  !<                                 coo_row_ind,
  !<                                 coo_col_ind,
  !<                                 perm,
  !<                                 temp_buffer);
  !< 
  !<     // Gather sorted coo_val array
  !<     float* coo_val_sorted;
