  !<     hipFree(coo_val);
  !< \endcode
  interface rocsparse_coosort_by_column
    function rocsparse_coosort_by_column_(handle,m,n,nnz,coo_row_ind,coo_col_ind,perm,temp_buffer) bind(c, name="rocsparse_coosort_by_column")
      use iso_c_binding

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: m
      integer(kind=c_int), value :: n
      integer(kind=c_int), value :: nnz
      type(c_ptr), value :: coo_row_ind
      type(c_ptr), value :: coo_col_ind
      type(c_ptr), value :: perm
      type(c_ptr), value :: temp_buffer
      integer(kind(rocsparse_status_)) :: rocsparse_coosort_by_column
    end function

  end interface


  !<  \ingroup conv_module
  !< \brief
  !< This function converts the sparse matrix in CSC format into a dense matrix.
  !< 
  !< \note
  !< This function is non blocking and executed asynchronously with respect to the host.
  !< It may return before the actual computation has finished.
  !< 
  !< \note
  !< This routine supports execution in a hipGraph context.
  !< 
  !< @param[in]
  !< handle      handle to the rocsparse library context queue.
  !< 
  !< @param[in]
  !< m           number of rows of the dense matrix \p A.
  !< 
  !< @param[in]
  !< n           number of columns of the dense matrix \p A.
  !< 
  !< @param[in]
  !< descr       the descriptor of the dense matrix \p A, the supported matrix type is \ref rocsparse_matrix_type_general and also any valid value of the \ref rocsparse_index_base.
  !< 
  !< @param[in]
  !< csc_val     array of nnz ( = \p csc_col_ptr[m] - \p csc_col_ptr[0] ) nonzero elements of matrix \p A.
  !< @param[in]
  !< csc_col_ptr integer array of m+1 elements that contains the start of every row and the end of the last row plus one.
  !< @param[in]
  !< csc_row_ind integer array of nnz ( = \p csc_col_ptr[m] - csc_col_ptr[0] ) column indices of the non-zero elements of matrix \p A.
  !< 
  !< @param[out]
  !< A           array of dimensions (\p ld, \p n)
  !< 
  !< @param[out]
  !< ld          leading dimension of dense array \p A.
  !< 
  !< \retval     rocsparse_status_success the operation completed successfully.
  !< \retval     rocsparse_status_invalid_handle the library context was not initialized.
  !< \retval     rocsparse_status_invalid_size \p m or \p n or \p ld is invalid.
  !< \retval     rocsparse_status_invalid_pointer \p A or \p csc_val \p csc_col_ptr or \p csc_row_ind
  !<             pointer is invalid.
  !< 
  !< @{*/
  interface rocsparse_scsc2dense
    function rocsparse_scsc2dense_(handle,m,n,descr,csc_val,csc_col_ptr,csc_row_ind,A,ld) bind(c, name="rocsparse_scsc2dense")
      use iso_c_binding

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: m
      integer(kind=c_int), value :: n
      type(c_ptr), value :: descr
      type(c_ptr), value :: csc_val
      type(c_ptr), value :: csc_col_ptr
      type(c_ptr), value :: csc_row_ind
      type(c_ptr), value :: A
      integer(kind=c_int), value :: ld
      integer(kind(rocsparse_status_)) :: rocsparse_scsc2dense
    end function

  end interface



