  !< required by rocsparse_sgebsr2gebsc(), rocsparse_dgebsr2gebsc(), rocsparse_cgebsr2gebsc() and
  !< rocsparse_zgebsr2gebsc(). The temporary storage buffer must be allocated by the user.
  !< 
  !< \note
