  !<  \ingroup generic_module
  !< \brief Scale a sparse vector and add it to a scaled dense vector.
  !< 
  !< \details
  !< \ref rocsparse_axpby multiplies the sparse vector \f$x\f$ with scalar \f$\alpha\f$ and
  !< adds the result to the dense vector \f$y\f$ that is multiplied with scalar
  !< \f$\beta\f$, such that
  !< 
  !< \f[
  !<     y := \alpha \cdot x + \beta \cdot y
  !< \f]
  !< 
  !< \code{.c}
  !<     for(i = 0; i < nnz; ++i)
  !<     {
  !<         y[x_ind[i]] = alpha * x_val[i] + beta * y[x_ind[i]]
  !<     }
  !< \endcode
  !< 
  !< \note
  !< This function is non blocking and executed asynchronously with respect to the host.
  !< It may return before the actual computation has finished.
  !< 
  !< \note
  !< This routine supports execution in a hipGraph context.
  !< 
  !< @param[in]
  !< handle      handle to the rocsparse library context queue.
  !< @param[in]
  !< alpha       scalar \f$\alpha\f$.
  !< @param[in]
  !< x           sparse matrix descriptor.
  !< @param[in]
  !< beta        scalar \f$\beta\f$.
  !< @param[inout]
  !< y           dense matrix descriptor.
  !< 
  !< \retval rocsparse_status_success the operation completed successfully.
  !< \retval rocsparse_status_invalid_handle the library context was not initialized.
  !< \retval rocsparse_status_invalid_pointer \p alpha, \p x, \p beta or \p y pointer is
  !<         invalid.
  !< 
  !< \par Example
  !< \code{.c}
  !<  // Number of non-zeros of the sparse vector
  !<  int nnz = 3;
  !< 
  !<  // Size of sparse and dense vector
  !<  int size = 9;
  !< 
  !<  // Sparse index vector
  !<  std::vector<int> hx_ind = {0, 3, 5};
  !< 
  !<  // Sparse value vector
  !<  std::vector<float> hx_val = {1.0f, 2.0f, 3.0f};
  !< 
  !<  // Dense vector
  !<  std::vector<float> hy = {1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f};
  !< 
  !<  // Scalar alpha
  !<  float alpha = 3.7f;
  !< 
  !<  // Scalar beta
  !<  float beta = 1.2f;
  !< 
  !<  // Offload data to device
  !<  int* dx_ind;
  !<  float* dx_val;
  !<  float* dy;
  !<  hipMalloc((void**)&dx_ind, sizeof(int) * nnz);
  !<  hipMalloc((void**)&dx_val, sizeof(float) * nnz);
  !<  hipMalloc((void**)&dy, sizeof(float) * size);
  !< 
  !<  hipMemcpy(dx_ind, hx_ind.data(), sizeof(int) * nnz, hipMemcpyHostToDevice);
  !<  hipMemcpy(dx_val, hx_val.data(), sizeof(float) * nnz, hipMemcpyHostToDevice);
  !<  hipMemcpy(dy, hy.data(), sizeof(float) * size, hipMemcpyHostToDevice);
  !< 
  !<  rocsparse_handle     handle;
  !<  rocsparse_spvec_descr vecX;
  !<  rocsparse_dnvec_descr vecY;
  !< 
  !<  rocsparse_indextype idx_type = rocsparse_indextype_i32;
  !<  rocsparse_datatype  data_type = rocsparse_datatype_f32_r;
  !<  rocsparse_index_base idx_base = rocsparse_index_base_zero;
  !< 
  !<  rocsparse_create_handle(&handle);
  !< 
  !<  // Create sparse vector X
  !<  rocsparse_create_spvec_descr(&vecX,
  !<                               size,
  !<                               nnz,
  !<                               dx_ind,
  !<                               dx_val,
  !<                               idx_type,
  !<                               idx_base,
  !<                               data_type);
  !< 
  !<  // Create dense vector Y
  !<  rocsparse_create_dnvec_descr(&vecY,
  !<                               size,
  !<                               dy,
  !<                               data_type);
  !< 
  !<  // Call axpby to perform y = beta * y + alpha * x
  !<  rocsparse_axpby(handle,
  !<                  &alpha,
  !<                  vecX,
  !<                  &beta,
  !<                  vecY);
  !< 
  !<  rocsparse_dnvec_get_values(vecY, (void**)&dy);
  !< 
  !<  // Copy result back to host
  !<  hipMemcpy(hy.data(), dy, sizeof(float) * size, hipMemcpyDeviceToHost);
  !< 
  !<  std::cout << "y" << std::endl;
  !<  for(size_t i = 0; i < hy.size(); ++i)
  !<  {
  !<      std::cout << hy[i] << " ";
  !<  }
  !<  std::cout << std::endl;
  !< 
  !<  // Clear rocSPARSE
  !<  rocsparse_destroy_spvec_descr(vecX);
  !<  rocsparse_destroy_dnvec_descr(vecY);
  !<  rocsparse_destroy_handle(handle);
  !< 
  !<  // Clear device memory
  !<  hipFree(dx_ind);
  !<  hipFree(dx_val);
  !<  hipFree(dy);
  !< \endcode
  interface rocsparse_axpby
    function rocsparse_axpby_(handle,alpha,x,beta,y) bind(c, name="rocsparse_axpby")
      use iso_c_binding

      implicit none
      type(c_ptr), value :: handle
      type(c_ptr), value :: alpha
      type(c_ptr), value :: x
      type(c_ptr), value :: beta
      type(c_ptr), value :: y
      integer(kind(rocsparse_status_)) :: rocsparse_axpby
    end function

  end interface


  !<  \ingroup generic_module
  !< \brief Gather elements from a dense vector and store them into a sparse vector.
  !< 
  !< \details
  !< \ref rocsparse_gather gathers the elements from the dense vector \f$y\f$ and stores
  !< them in the sparse vector \f$x\f$.
  !< 
  !< \code{.c}
  !<     for(i = 0; i < nnz; ++i)
  !<     {
  !<         x_val[i] = y[x_ind[i]];
  !<     }
  !< \endcode
  !< 
  !< \par Uniform Precisions:
  !< <table>
  !< <caption id="gather_uniform">Uniform Precisions</caption>
  !< <tr><th>X / Y
  !< <tr><td>rocsparse_datatype_i8_r
  !< <tr><td>rocsparse_datatype_f32_r
  !< <tr><td>rocsparse_datatype_f64_r
  !< <tr><td>rocsparse_datatype_f32_c
  !< <tr><td>rocsparse_datatype_f64_c
  !< </table>
  !< 
  !< \note
  !< This function is non blocking and executed asynchronously with respect to the host.
  !< It may return before the actual computation has finished.
  !< 
  !< \note
  !< This routine supports execution in a hipGraph context.
  !< 
  !< @param[in]
  !< handle       handle to the rocsparse library context queue.
  !< @param[in]
  !< y            dense vector \f$y\f$.
  !< @param[out]
  !< x            sparse vector \f$x\f$.
  !< 
  !< \retval      rocsparse_status_success the operation completed successfully.
  !< \retval      rocsparse_status_invalid_handle the library context was not initialized.
  !< \retval      rocsparse_status_invalid_pointer \p x or \p y pointer is invalid.
  !< 
  !< \par Example
  !< \code{.c}
  !<  // Number of non-zeros of the sparse vector
  !<  int nnz = 3;
  !< 
  !<  // Size of sparse and dense vector
  !<  int size = 9;
  !< 
  !<  // Sparse index vector
  !<  std::vector<int> hx_ind = {0, 3, 5};
  !< 
  !<  // Dense vector
  !<  std::vector<float> hy = {1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f};
  !< 
  !<  // Offload data to device
  !<  int* dx_ind;
  !<  float* dx_val;
  !<  float* dy;
  !<  hipMalloc((void**)&dx_ind, sizeof(int) * nnz);
  !<  hipMalloc((void**)&dx_val, sizeof(float) * nnz);
  !<  hipMalloc((void**)&dy, sizeof(float) * size);
  !< 
  !<  hipMemcpy(dx_ind, hx_ind.data(), sizeof(int) * nnz, hipMemcpyHostToDevice);
  !<  hipMemcpy(dy, hy.data(), sizeof(float) * size, hipMemcpyHostToDevice);
  !< 
  !<  rocsparse_handle     handle;
  !<  rocsparse_spvec_descr vecX;
  !<  rocsparse_dnvec_descr vecY;
  !< 
  !<  rocsparse_indextype idx_type = rocsparse_indextype_i32;
  !<  rocsparse_datatype  data_type = rocsparse_datatype_f32_r;
  !<  rocsparse_index_base idx_base = rocsparse_index_base_zero;
  !< 
  !<  rocsparse_create_handle(&handle);
  !< 
  !<  // Create sparse vector X
  !<  rocsparse_create_spvec_descr(&vecX,
  !<                               size,
  !<                               nnz,
  !<                               dx_ind,
  !<                               dx_val,
  !<                               idx_type,
  !<                               idx_base,
  !<                               data_type);
  !< 
  !<  // Create dense vector Y
  !<  rocsparse_create_dnvec_descr(&vecY,
  !<                               size,
  !<                               dy,
  !<                               data_type);
  !< 
  !<  // Call axpby to perform gather
  !<  rocsparse_gather(handle, vecY, vecX);
  !< 
  !<  rocsparse_spvec_get_values(vecX, (void**)&dx_val);
  !< 
  !<  // Copy result back to host
  !<  std::vector<float> hx_val(nnz, 0.0f);
  !<  hipMemcpy(hx_val.data(), dx_val, sizeof(float) * nnz, hipMemcpyDeviceToHost);
  !< 
  !<  std::cout << "x" << std::endl;
  !<  for(size_t i = 0; i < hx_val.size(); ++i)
  !<  {
  !<      std::cout << hx_val[i] << " ";
  !<  }
  !< 
  !<  std::cout << std::endl;
  !< 
  !<  // Clear rocSPARSE
  !<  rocsparse_destroy_spvec_descr(vecX);
  !<  rocsparse_destroy_dnvec_descr(vecY);
  !<  rocsparse_destroy_handle(handle);
  !< 
  !<  // Clear device memory
  !<  hipFree(dx_ind);
  !<  hipFree(dx_val);
  !<  hipFree(dy);
  !< \endcode
  interface rocsparse_gather
    function rocsparse_gather_(handle,y,x) bind(c, name="rocsparse_gather")
      use iso_c_binding

      implicit none
      type(c_ptr), value :: handle
      type(c_ptr), value :: y
      type(c_ptr), value :: x
      integer(kind(rocsparse_status_)) :: rocsparse_gather
    end function

  end interface


  !<  \ingroup generic_module
  !< \brief Apply Givens rotation to a dense and a sparse vector.
  !< 
  !< \details
  !< \ref rocsparse_rot applies the Givens rotation matrix \f$G\f$ to the sparse vector
  !< \f$x\f$ and the dense vector \f$y\f$, where
  !< \f[
  !<   G = \begin{pmatrix} c & s \\ -s & c \end{pmatrix}
  !< \f]
  !< 
  !< \code{.c}
  !<     for(i = 0; i < nnz; ++i)
  !<     {
  !<         x_tmp = x_val[i];
  !<         y_tmp = y[x_ind[i]];
  !< 
  !<         x_val[i]    = c * x_tmp + s * y_tmp;
  !<         y[x_ind[i]] = c * y_tmp - s * x_tmp;
  !<     }
  !< \endcode
  !< 
  !< \note
  !< This function is non blocking and executed asynchronously with respect to the host.
  !< It may return before the actual computation has finished.
  !< 
  !< \note
  !< This routine supports execution in a hipGraph context.
  !< 
  !< @param[in]
  !< handle      handle to the rocsparse library context queue.
  !< @param[in]
  !< c           pointer to the cosine element of \f$G\f$, can be on host or device.
  !< @param[in]
  !< s           pointer to the sine element of \f$G\f$, can be on host or device.
  !< @param[inout]
  !< x           sparse vector \f$x\f$.
  !< @param[inout]
  !< y           dense vector \f$y\f$.
  !< 
  !< \retval     rocsparse_status_success the operation completed successfully.
  !< \retval     rocsparse_status_invalid_handle the library context was not initialized.
  !< \retval     rocsparse_status_invalid_pointer \p c, \p s, \p x or \p y pointer is
  !<             invalid.
  !< \par Example
  !< \code{.c}
  !<  // Number of non-zeros of the sparse vector
  !<  int nnz = 3;
  !< 
  !<  // Size of sparse and dense vector
  !<  int size = 9;
  !< 
  !<  // Sparse index vector
  !<  std::vector<int> hx_ind = {0, 3, 5};
  !< 
  !<  // Sparse value vector
  !<  std::vector<float> hx_val = {1.0f, 2.0f, 3.0f};
  !< 
  !<  // Dense vector
  !<  std::vector<float> hy = {1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f};
  !< 
  !<  // Scalar c
  !<  float c = 3.7f;
  !< 
  !<  // Scalar s
  !<  float s = 1.2f;
  !< 
  !<  // Offload data to device
  !<  int* dx_ind;
  !<  float* dx_val;
  !<  float* dy;
  !<  hipMalloc((void**)&dx_ind, sizeof(int) * nnz);
  !<  hipMalloc((void**)&dx_val, sizeof(float) * nnz);
  !<  hipMalloc((void**)&dy, sizeof(float) * size);
  !< 
  !<  hipMemcpy(dx_ind, hx_ind.data(), sizeof(int) * nnz, hipMemcpyHostToDevice);
  !<  hipMemcpy(dx_val, hx_val.data(), sizeof(float) * nnz, hipMemcpyHostToDevice);
  !<  hipMemcpy(dy, hy.data(), sizeof(float) * size, hipMemcpyHostToDevice);
  !< 
  !<  rocsparse_handle     handle;
  !<  rocsparse_spvec_descr vecX;
  !<  rocsparse_dnvec_descr vecY;
  !< 
  !<  rocsparse_indextype idx_type = rocsparse_indextype_i32;
  !<  rocsparse_datatype  data_type = rocsparse_datatype_f32_r;
  !<  rocsparse_index_base idx_base = rocsparse_index_base_zero;
  !< 
  !<  rocsparse_create_handle(&handle);
  !< 
  !<  // Create sparse vector X
  !<  rocsparse_create_spvec_descr(&vecX,
  !<                               size,
  !<                               nnz,
  !<                               dx_ind,
  !<                               dx_val,
  !<                               idx_type,
  !<                               idx_base,
  !<                               data_type);
  !< 
  !<  // Create dense vector Y
  !<  rocsparse_create_dnvec_descr(&vecY,
  !<                               size,
  !<                               dy,
  !<                               data_type);
  !< 
  !<  // Call rot
  !<  rocsparse_rot(handle, (void*)&c, (void*)&s, vecX, vecY);
  !< 
  !<  rocsparse_spvec_get_values(vecX, (void**)&dx_val);
  !<  rocsparse_dnvec_get_values(vecY, (void**)&dy);
  !< 
  !<  // Copy result back to host
  !<  hipMemcpy(hx_val.data(), dx_val, sizeof(float) * nnz, hipMemcpyDeviceToHost);
  !<  hipMemcpy(hy.data(), dy, sizeof(float) * size, hipMemcpyDeviceToHost);
  !< 
  !<  std::cout << "x" << std::endl;
  !<  for(size_t i = 0; i < hx_val.size(); ++i)
  !<  {
  !<      std::cout << hx_val[i] << " ";
  !<  }
  !< 
  !<  std::cout << std::endl;
  !< 
  !<  std::cout << "y" << std::endl;
  !<  for(size_t i = 0; i < hy.size(); ++i)
  !<  {
  !<      std::cout << hy[i] << " ";
  !<  }
  !< 
  !<  std::cout << std::endl;
  !< 
  !<  // Clear rocSPARSE
  !<  rocsparse_destroy_spvec_descr(vecX);
  !<  rocsparse_destroy_dnvec_descr(vecY);
  !<  rocsparse_destroy_handle(handle);
  !< 
  !<  // Clear device memory
  !<  hipFree(dx_ind);
  !<  hipFree(dx_val);
  !<  hipFree(dy);
  !< \endcode
  interface rocsparse_rot
    function rocsparse_rot_(handle,c,s,x,y) bind(c, name="rocsparse_rot")
      use iso_c_binding

      implicit none
      type(c_ptr), value :: handle
      type(c_ptr), value :: c
      type(c_ptr), value :: s
      type(c_ptr), value :: x
      type(c_ptr), value :: y
      integer(kind(rocsparse_status_)) :: rocsparse_rot
    end function

  end interface


  !<  \ingroup generic_module
  !< \brief Scatter elements from a sparse vector into a dense vector.
  !< 
  !< \details
  !< \ref rocsparse_scatter scatters the elements from the sparse vector \f$x\f$ in the dense
  !< vector \f$y\f$.
  !< 
  !< \code{.c}
  !<     for(i = 0; i < nnz; ++i)
  !<     {
  !<         y[x_ind[i]] = x_val[i];
  !<     }
  !< \endcode
  !< 
  !< \par Uniform Precisions:
  !< <table>
  !< <caption id="scatter_uniform">Uniform Precisions</caption>
  !< <tr><th>X / Y
  !< <tr><td>rocsparse_datatype_i8_r
  !< <tr><td>rocsparse_datatype_f32_r
  !< <tr><td>rocsparse_datatype_f64_r
  !< <tr><td>rocsparse_datatype_f32_c
  !< <tr><td>rocsparse_datatype_f64_c
  !< </table>
  !< 
  !< \note
  !< This function is non blocking and executed asynchronously with respect to the host.
  !< It may return before the actual computation has finished.
  !< 
  !< \note
  !< This routine supports execution in a hipGraph context.
  !< 
  !< @param[in]
  !< handle       handle to the rocsparse library context queue.
  !< @param[in]
  !< x            sparse vector \f$x\f$.
  !< @param[out]
  !< y            dense vector \f$y\f$.
  !< 
  !< \retval      rocsparse_status_success the operation completed successfully.
  !< \retval      rocsparse_status_invalid_handle the library context was not initialized.
  !< \retval      rocsparse_status_invalid_pointer \p x or \p y pointer is invalid.
  !< 
  !< \par Example
  !< \code{.c}
  !<  // Number of non-zeros of the sparse vector
  !<  int nnz = 3;
  !< 
  !<  // Size of sparse and dense vector
  !<  int size = 9;
  !< 
  !<  // Sparse index vector
  !<  std::vector<int> hx_ind = {0, 3, 5};
  !< 
  !<  // Sparse value vector
  !<  std::vector<float> hx_val = {1.0f, 2.0f, 3.0f};
  !< 
  !<  // Dense vector
  !<  std::vector<float> hy = {1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f};
  !< 
  !<  // Offload data to device
  !<  int* dx_ind;
  !<  float* dx_val;
  !<  float* dy;
  !<  hipMalloc((void**)&dx_ind, sizeof(int) * nnz);
  !<  hipMalloc((void**)&dx_val, sizeof(float) * nnz);
  !<  hipMalloc((void**)&dy, sizeof(float) * size);
  !< 
  !<  hipMemcpy(dx_ind, hx_ind.data(), sizeof(int) * nnz, hipMemcpyHostToDevice);
  !<  hipMemcpy(dx_val, hx_val.data(), sizeof(float) * nnz, hipMemcpyHostToDevice);
  !<  hipMemcpy(dy, hy.data(), sizeof(float) * size, hipMemcpyHostToDevice);
  !< 
  !<  rocsparse_handle     handle;
  !<  rocsparse_spvec_descr vecX;
  !<  rocsparse_dnvec_descr vecY;
  !< 
  !<  rocsparse_indextype idx_type = rocsparse_indextype_i32;
  !<  rocsparse_datatype  data_type = rocsparse_datatype_f32_r;
  !<  rocsparse_index_base idx_base = rocsparse_index_base_zero;
  !< 
  !<  rocsparse_create_handle(&handle);
  !< 
  !<  // Create sparse vector X
  !<  rocsparse_create_spvec_descr(&vecX,
  !<                               size,
  !<                               nnz,
  !<                               dx_ind,
  !<                               dx_val,
  !<                               idx_type,
  !<                               idx_base,
  !<                               data_type);
  !< 
  !<  // Create dense vector Y
  !<  rocsparse_create_dnvec_descr(&vecY,
  !<                               size,
  !<                               dy,
  !<                               data_type);
  !< 
  !<  // Call axpby to perform scatter
  !<  rocsparse_scatter(handle, vecX, vecY);
  !< 
  !<  rocsparse_dnvec_get_values(vecY, (void**)&dy);
  !< 
  !<  // Copy result back to host
  !<  hipMemcpy(hy.data(), dy, sizeof(float) * size, hipMemcpyDeviceToHost);
  !< 
  !<  std::cout << "y" << std::endl;
  !<  for(size_t i = 0; i < hy.size(); ++i)
  !<  {
  !<      std::cout << hy[i] << " ";
  !<  }
  !< 
  !<  std::cout << std::endl;
  !< 
  !<  // Clear rocSPARSE
  !<  rocsparse_destroy_spvec_descr(vecX);
  !<  rocsparse_destroy_dnvec_descr(vecY);
  !<  rocsparse_destroy_handle(handle);
  !< 
  !<  // Clear device memory
  !<  hipFree(dx_ind);
  !<  hipFree(dx_val);
  !<  hipFree(dy);
  !< \endcode
  interface rocsparse_scatter
    function rocsparse_scatter_(handle,x,y) bind(c, name="rocsparse_scatter")
      use iso_c_binding

      implicit none
      type(c_ptr), value :: handle
      type(c_ptr), value :: x
      type(c_ptr), value :: y
      integer(kind(rocsparse_status_)) :: rocsparse_scatter
    end function

  end interface


  !<  \ingroup level2_module
  !< \brief Sparse matrix vector multiplication using BSR storage format
  !< 
  !< \details
  !< \p rocsparse_bsrmv_ex_clear deallocates all memory that was allocated by
  !< rocsparse_sbsrmv_ex_analysis(), rocsparse_dbsrmv_ex_analysis(), rocsparse_cbsrmv_ex_analysis()
  !< or rocsparse_zbsrmv_ex_analysis(). This is especially useful, if memory is an issue and
  !< the analysis data is not required anymore for further computation, e.g. when
  !< switching to another sparse matrix format.
  !< 
  !< \note
  !< Calling \p rocsparse_bsrmv_ex_clear is optional. All allocated resources will be
  !< cleared, when the opaque \ref rocsparse_mat_info struct is destroyed using
  !< rocsparse_destroy_mat_info().
  !< 
  !< \note
  !< This routine does not support execution in a hipGraph context.
  !< 
  !< @param[in]
  !< handle      handle to the rocsparse library context queue.
  !< @param[inout]
  !< info        structure that holds the information collected during analysis step.
  !< 
  !< \retval     rocsparse_status_success the operation completed successfully.
  !< \retval     rocsparse_status_invalid_handle the library context was not initialized.
  !< \retval     rocsparse_status_invalid_pointer \p info pointer is invalid.
  !< \retval     rocsparse_status_memory_error the buffer for the gathered information
  !<             could not be deallocated.
  !< \retval     rocsparse_status_internal_error an internal error occurred.
  interface rocsparse_bsrmv_ex_clear
    function rocsparse_bsrmv_ex_clear_(handle,info) bind(c, name="rocsparse_bsrmv_ex_clear")
      use iso_c_binding

      implicit none
      type(c_ptr), value :: handle
      type(c_ptr), value :: info
      integer(kind(rocsparse_status_)) :: rocsparse_bsrmv_ex_clear
    end function

  end interface


  !<  \ingroup level2_module
  !< \brief Sparse matrix vector multiplication using BSR storage format
  !< 
  !< \details
  !< \p rocsparse_bsrmv_clear deallocates all memory that was allocated by
  !< rocsparse_sbsrmv_analysis(), rocsparse_dbsrmv_analysis(), rocsparse_cbsrmv_analysis()
  !< or rocsparse_zbsrmv_analysis(). This is especially useful, if memory is an issue and
  !< the analysis data is not required anymore for further computation, e.g. when
  !< switching to another sparse matrix format.
  !< 
  !< \note
  !< Calling \p rocsparse_bsrmv_clear is optional. All allocated resources will be
  !< cleared, when the opaque \ref rocsparse_mat_info struct is destroyed using
  !< rocsparse_destroy_mat_info().
  !< 
  !< \note
  !< This routine does not support execution in a hipGraph context.
  !< 
  !< @param[in]
  !< handle      handle to the rocsparse library context queue.
  !< @param[inout]
  !< info        structure that holds the information collected during analysis step.
  !< 
  !< \retval     rocsparse_status_success the operation completed successfully.
  !< \retval     rocsparse_status_invalid_handle the library context was not initialized.
  !< \retval     rocsparse_status_invalid_pointer \p info pointer is invalid.
  !< \retval     rocsparse_status_memory_error the buffer for the gathered information
  !<             could not be deallocated.
  !< \retval     rocsparse_status_internal_error an internal error occurred.
  interface rocsparse_bsrmv_clear
    function rocsparse_bsrmv_clear_(handle,info) bind(c, name="rocsparse_bsrmv_clear")
      use iso_c_binding

      implicit none
      type(c_ptr), value :: handle
      type(c_ptr), value :: info
      integer(kind(rocsparse_status_)) :: rocsparse_bsrmv_clear
    end function

  end interface


  !<  \ingroup level2_module
  !< \brief Sparse triangular solve using BSR storage format
  !< 
  !< \details
  !< \p rocsparse_bsrsv_zero_pivot returns \ref rocsparse_status_zero_pivot, if either a
  !< structural or numerical zero has been found during rocsparse_sbsrsv_solve(),
  !< rocsparse_dbsrsv_solve(), rocsparse_cbsrsv_solve() or rocsparse_zbsrsv_solve()
  !< computation. The first zero pivot \f$j\f$ at \f$A_{j,j}\f$ is stored in \p position,
  !< using same index base as the BSR matrix.
  !< 
  !< \p position can be in host or device memory. If no zero pivot has been found,
  !< \p position is set to -1 and \ref rocsparse_status_success is returned instead.
  !< 
  !< \note \p rocsparse_bsrsv_zero_pivot is a blocking function. It might influence
  !< performance negatively.
  !< 
  !< \note
  !< This routine does not support execution in a hipGraph context.
  !< 
  !< @param[in]
  !< handle      handle to the rocsparse library context queue.
  !< @param[in]
  !< info        structure that holds the information collected during the analysis step.
  !< @param[inout]
  !< position    pointer to zero pivot \f$j\f$, can be in host or device memory.
  !< 
  !< \retval     rocsparse_status_success the operation completed successfully.
  !< \retval     rocsparse_status_invalid_handle the library context was not initialized.
  !< \retval     rocsparse_status_invalid_pointer \p info or \p position pointer is
  !<             invalid.
  !< \retval     rocsparse_status_internal_error an internal error occurred.
  !< \retval     rocsparse_status_zero_pivot zero pivot has been found.
  interface rocsparse_bsrsv_zero_pivot
    function rocsparse_bsrsv_zero_pivot_(handle,info,position) bind(c, name="rocsparse_bsrsv_zero_pivot")
      use iso_c_binding

      implicit none
      type(c_ptr), value :: handle
      type(c_ptr), value :: info
      type(c_ptr), value :: position
      integer(kind(rocsparse_status_)) :: rocsparse_bsrsv_zero_pivot
    end function

  end interface


  !<  \ingroup level2_module
  !< \brief Sparse triangular solve using BSR storage format
